-- GameXS editorial overviews, part 7 (ps5_games.overview, migration 040).
--
-- Same format and rules as db/content/game_overviews.sql: original Persian copy
-- written for GameXS; no text was copied. Facts checked against the IGDB data
-- stored in ps5_games.
--
-- Shape: {"intro", "suits": [..], "sections": [{"heading", "paragraphs": [..], "media"}]}
-- media = "trailer" | "screenshot:N" (1-based index into screenshot_ids); a key
-- the game has no asset for is skipped at render time.
--
-- Idempotent: re-running overwrites the overview of each listed slug and
-- touches nothing else. Apply with:
--   docker exec -i gamexs-postgres psql -U gamexs -d gamexs -v ON_ERROR_STOP=1 < db/content/game_overviews_part7.sql

UPDATE ps5_games g
SET overview = v.overview::jsonb
FROM (VALUES

('diablo-iv', $j${
  "intro": "Diablo IV چهارمین قسمت اصلی سری افسانه‌ای دیابلو از Blizzard Entertainment است؛ یک نقش‌آفرینی اکشن تاریک که در آن از زاویه بالا با موج بی‌پایانی از شیاطین می‌جنگید، غنیمت جمع می‌کنید و شخصیت‌تان را قدم‌به‌قدم قوی‌تر می‌کنید. این بار جهان سنکچری برای اولین بار در این سری به‌صورت یک دنیای باز و پیوسته طراحی شده است.",
  "suits": ["طرفداران نقش‌آفرینی اکشن", "عاشقان جمع‌آوری غنیمت", "بازی گروهی با دوستان"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "جنگ میان بهشت و دوزخ همچنان ادامه دارد و در این میان لیلیت، دختر مفیستو، دوباره به سنکچری بازگشته است. با آمدن او نفرت در دل مردم ریشه می‌دواند و فرقه‌هایی تازه به پرستش او روی می‌آورند. شما یکی از معدود قهرمانانی هستید که حاضرند در برابر این تاریکی بایستند.",
        "لحن بازی نسبت به قسمت سوم تیره‌تر و خشن‌تر است و به حال‌وهوای گوتیک دو قسمت اول سری نزدیک‌تر شده؛ روستاهای ویران، کلیساهای متروک و سیاه‌چال‌های خون‌آلود فضای اصلی ماجرا را می‌سازند."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "در ابتدا یک کلاس انتخاب می‌کنید، مثل بربرین، جادوگر، روگ، درویید یا نکرومنسر، و با امتیاز مهارت و درخت استعدادها سبک مبارزه‌اش را شکل می‌دهید. آیتم‌های افسانه‌ای و ویژگی‌های تصادفی‌شان باعث می‌شوند هر بیلد حس متفاوتی داشته باشد و همیشه دلیلی برای یک سیاه‌چال دیگر وجود داشته باشد.",
        "دنیای باز به چند منطقه بزرگ تقسیم شده و پر از رویدادهای جهانی، قلعه‌های قابل‌تسخیر و سیاه‌چال‌های تصادفی است. گاهی هم با بازیکنان دیگری روبه‌رو می‌شوید که در همان منطقه مشغول جنگ‌اند و می‌توانید با آن‌ها در برابر باس‌های جهانی متحد شوید."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "محتوای بعد از داستان",
      "paragraphs": [
        "تمام کردن کمپین تازه شروع کار است. سطوح سختی بالاتر، سیاه‌چال‌های چالشی و فصل‌های دوره‌ای با مکانیک‌ها و پاداش‌های تازه، Diablo IV را به بازی‌ای تبدیل کرده‌اند که خیلی‌ها ماه‌ها سراغش می‌روند. بازی را می‌توانید تنها یا در گروه‌های چندنفره با دوستان تجربه کنید."
      ],
      "media": "screenshot:6"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Diablo IV حتی در حالت تک‌نفره هم به اتصال دائمی اینترنت نیاز دارد، بنابراین اکانت ظرفیت ۱ که باید آفلاین بماند برای این بازی مناسب نیست. ظرفیت ۲ یا ۳ را انتخاب کنید؛ ظرفیت ۳ معمولاً ارزان‌تر است و چون بازی به‌هرحال آنلاین اجرا می‌شود، محدودیت آن در عمل کمتر به چشم می‌آید. اگر قصد بازی گروهی دارید، شرایط PS Plus را هم در نظر بگیرید و قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('life-is-strange-double-exposure', $j${
  "intro": "Life Is Strange Double Exposure بازگشت مکس کالفیلد، قهرمان اولین قسمت سری، است؛ این بار در قالب یک معمای قتل با دو خط زمانی موازی. بازی را استودیو Deck Nine ساخته و Square Enix منتشر کرده و مثل همیشه سری، تکیه اصلی آن بر داستان، شخصیت‌ها و انتخاب‌هایی است که مسیر ماجرا را عوض می‌کنند.",
  "suits": ["طرفداران بازی‌های داستان‌محور", "علاقه‌مندان معمای جنایی", "بازیکنان آرام‌پسند"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "سال‌ها از اتفاقات آرکادیا بی گذشته و مکس حالا عکاس مقیم دانشگاه معتبر کلیدون است. یک شب برفی، صفی، نزدیک‌ترین دوست تازه‌اش، را بی‌جان در برف پیدا می‌کند. مکس برای نجات او سراغ قدرتی می‌رود که سال‌ها کنار گذاشته بود، اما به‌جای بازگرداندن زمان، دری به یک خط زمانی دیگر باز می‌شود؛ جایی که صفی هنوز زنده است و همچنان در خطر.",
        "مکس می‌فهمد قاتل قرار است در هر دو واقعیت دوباره دست به کار شود و فقط خود اوست که می‌تواند میان این دو دنیا رفت‌وآمد کند و ماجرا را حل کند."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "هسته بازی گفت‌وگو، کاوش و انتخاب است. قدرت تازه مکس به او اجازه می‌دهد میان دو خط زمانی جابه‌جا شود یا برای لحظه‌ای نگاهی به دنیای دیگر بیندازد. بسیاری از معماها بر همین اساس طراحی شده‌اند: چیزی که در یک دنیا بسته است، شاید در دنیای دیگر باز باشد.",
        "داستان در چند فصل روایت می‌شود و تصمیم‌های شما روی روابط مکس با اطرافیان و اتفاقات بعدی اثر می‌گذارد. بازی اکشن یا مبارزه ندارد و ریتم آن آرام و سینمایی است."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر قسمت اول سری را دوست داشتید، دیدن مکس بزرگ‌ترشده برایتان جذاب خواهد بود؛ هرچند بازی طوری ساخته شده که بدون تجربه قسمت‌های قبل هم قابل‌فهم باشد. کسانی که دنبال داستانی احساسی با چاشنی معما و راز هستند، از آن لذت می‌برند."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "این بازی کاملاً تک‌نفره است و برای تجربه داستان به اینترنت نیازی ندارد. اکانت ظرفیت ۱ ارزان‌ترین راه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر نمی‌خواهید محدودیتی برای آنلاین شدن داشته باشید، ظرفیت ۲ انعطاف بیشتری دارد. قیمت روش‌های مختلف را در جدول همین صفحه ببینید."
      ]
    }
  ]
}$j$),

('life-is-strange-reunion', $j${
  "intro": "Life Is Strange Reunion فصل پایانی ماجرای مکس و کلویی است؛ دو شخصیتی که اولین قسمت سری با رابطه آن‌ها شناخته شد. بازی را Deck Nine ساخته و Square Enix منتشر کرده و ادامه مستقیم اتفاقات دانشگاه کلیدون در Double Exposure به حساب می‌آید.",
  "suits": ["طرفداران سری Life Is Strange", "بازیکنان داستان‌محور", "علاقه‌مندان روایت احساسی"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "کلویی پرایس روزگاری همراه مکس در سفرهای زمانی‌اش بود و از دست دادن او بزرگ‌ترین حسرت مکس است. حالا کلویی خودش به دانشگاه کلیدون آمده؛ آشفته از کابوس‌ها و خاطراتی که نباید وجود داشته باشند، و به کمک مکس نیاز دارد.",
        "اما مکس خودش در بحران است: تا سه روز دیگر آتش‌سوزی مرگباری کل دانشگاه را نابود می‌کند. قدرت بازگرداندن زمان دوباره کلید ماجراست و مکس باید هم راز گذشته کلویی را بفهمد و هم جلوی فاجعه را بگیرد."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مثل دیگر قسمت‌های سری، بازی بر پایه کاوش در محیط، گفت‌وگو با شخصیت‌ها و تصمیم‌گیری در لحظه‌های حساس است. توانایی عقب بردن زمان به شما اجازه می‌دهد نتیجه یک گفت‌وگو یا اتفاق را ببینید و در صورت لزوم آن را تغییر دهید. انتخاب‌ها روی روابط و سرانجام داستان اثر می‌گذارند."
      ],
      "media": "screenshot:3"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "این بازی بیش از همه برای کسانی ساخته شده که با مکس و کلویی خاطره دارند و می‌خواهند پایان داستان آن‌ها را ببینند. بهتر است پیش از آن Double Exposure را تجربه کرده باشید، چون اتفاقات و شخصیت‌های کلیدون مستقیماً ادامه پیدا می‌کنند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Life Is Strange Reunion یک تجربه تک‌نفره داستانی است و به اینترنت نیاز ندارد. اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول پس از نصب آفلاین بماند. ظرفیت ۲ برای کسانی بهتر است که می‌خواهند آزادانه آنلاین شوند. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('directive-8020-deluxe-edition', $j${
  "intro": "Directive 8020 یک بازی وحشت علمی‌تخیلی از Supermassive Games، سازندگان Until Dawn و مجموعه The Dark Pictures، است که Bandai Namco آن را منتشر کرده. بازی مثل دیگر آثار این استودیو داستانی سینمایی با انتخاب‌های سرنوشت‌ساز دارد، اما این بار ماجرا به اعماق فضا و سیاره‌ای ناشناخته منتقل شده است. نسخه Deluxe علاوه بر بازی اصلی محتوای اضافه هم دارد که جزئیاتش را در توضیحات هر فروشنده ببینید.",
  "suits": ["طرفداران وحشت علمی‌تخیلی", "علاقه‌مندان بازی‌های انتخاب‌محور", "طرفداران Until Dawn"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "زمین در حال مرگ است و وقت بشر رو به پایان. در دوازده سال نوری آن طرف‌تر، سیاره تاو سِتی اف آخرین روزنه امید است. اما وقتی سفینه مهاجرنشین کاسیوپیا روی این سیاره سقوط می‌کند، خدمه خیلی زود می‌فهمند که تنها نیستند.",
        "موجودی بیگانه آن‌ها را شکار می‌کند که می‌تواند شکل طعمه‌اش را تقلید کند. همین ویژگی فضای بازی را پر از بی‌اعتمادی می‌کند؛ هر کدام از همراهان شما ممکن است دیگر خودش نباشد."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "شما کنترل چند شخصیت مختلف را در طول داستان به دست می‌گیرید و در لحظه‌های حساس باید سریع تصمیم بگیرید. هر شخصیت ممکن است بسته به انتخاب‌های شما زنده بماند یا از دست برود و داستان بر اساس همین تصمیم‌ها شاخه‌شاخه می‌شود.",
        "در کنار روایت سینمایی، بخش‌های کاوش و مخفی شدن از موجود بیگانه هم نقش پررنگی دارند و تنش را بالا نگه می‌دارند. ساختار شاخه‌ای داستان باعث می‌شود تجربه دوباره بازی برای دیدن پایان‌های دیگر ارزشمند باشد."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر از Until Dawn یا The Quarry لذت برده‌اید و دوست دارید همان فرمول را در فضایی شبیه فیلم‌های وحشت فضایی کلاسیک تجربه کنید، Directive 8020 انتخاب مناسبی است. بازی امکان تجربه همراه دیگران را هم دارد و برای یک شب ترسناک دوستانه گزینه خوبی است."
      ],
      "media": "screenshot:7"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "داستان اصلی را می‌توانید به‌تنهایی و بدون اینترنت تجربه کنید؛ در این حالت اکانت ظرفیت ۱ ارزان‌ترین راه است، به شرط این‌که کنسول آفلاین بماند. اگر می‌خواهید بخش‌های چندنفره آنلاین را هم امتحان کنید، ظرفیت ۲ یا ۳ را انتخاب کنید و در نظر داشته باشید که بازی آنلاین روی PS5 معمولاً به PS Plus نیاز دارد. قیمت‌ها را در جدول همین صفحه ببینید."
      ]
    }
  ]
}$j$),

('one-piece-odyssey', $j${
  "intro": "One Piece Odyssey یک نقش‌آفرینی نوبتی بر اساس انیمه و مانگای محبوب وان پیس است که استودیو ILCA آن را ساخته و Bandai Namco منتشر کرده. در این بازی کنترل لوفی و خدمه کلاه‌حصیری را به دست می‌گیرید و در جزیره‌ای مرموز، ماجرایی تازه را تجربه می‌کنید که هم برای طرفداران قدیمی جذاب است و هم برای تازه‌واردها قابل‌فهم.",
  "suits": ["طرفداران وان پیس", "علاقه‌مندان نقش‌آفرینی نوبتی", "بازیکنان ماجراجو"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "لوفی و دوستانش در دریای دنیای جدید سرگرم سفرند که طوفانی سهمگین کشتی‌شان را درهم می‌شکند. آن‌ها خود را در جزیره‌ای استوایی و سرسبز می‌یابند که با طوفان‌های دائمی محاصره شده است. خیلی زود اتفاقی عجیب باعث می‌شود اعضای خدمه بیشتر قدرت‌هایشان را از دست بدهند.",
        "برای پس گرفتن توانایی‌ها، کلاه‌حصیری‌ها باید به سفری در خاطرات خودشان بروند؛ جایی که لحظه‌هایی آشنا از ماجراهای گذشته سری با تغییراتی تازه بازسازی شده‌اند. این ایده هم نوستالژی فراوانی برای طرفداران دارد و هم داستان را برای تازه‌واردها مرور می‌کند."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "مبارزه‌ها نوبتی‌اند و اعضای گروه به دو دسته فعال و ذخیره تقسیم می‌شوند. هر شخصیت سبک مبارزه خودش را دارد و یک سیستم سنگ‌کاغذقیچی میان انواع حمله تعیین می‌کند کدام عضو در برابر کدام دشمن مؤثرتر است. نکته جالب این‌که همه اعضا، حتی ذخیره‌ها، تجربه دریافت می‌کنند و لازم نیست نگران عقب ماندن کسی باشید.",
        "بیرون از مبارزه، هر عضو گروه توانایی ویژه‌ای برای کاوش دارد؛ مثلاً لوفی با دست‌های کشسانش به جاهای دور می‌رسد. سیاه‌چال‌ها، معماها و مأموریت‌های جانبی هم در کنار داستان اصلی قرار دارند."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر وان پیس را دوست دارید، این بازی یکی از وفادارترین اقتباس‌های آن است. سختی بازی نسبتاً ملایم است و برای کسانی که تازه با نقش‌آفرینی‌های نوبتی آشنا می‌شوند هم مناسب است."
      ],
      "media": "screenshot:6"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
