('grand-theft-auto-the-trilogy', $j${
  "intro": "Grand Theft Auto The Trilogy مجموعه‌ای از سه بازی کلاسیک Rockstar است که سری GTA را وارد دنیای سه‌بعدی کردند و سبک جهان‌باز را برای همیشه تغییر دادند: GTA III، Vice City و San Andreas. هر کدام از این بازی‌ها شهر، دوره و قهرمان خودش را دارد و با هم یکی از مهم‌ترین مجموعه‌های تاریخ بازی‌های ویدیویی را می‌سازند.",
  "suits": ["طرفداران GTA", "علاقه‌مندان بازی‌های نوستالژیک", "طرفداران جهان‌باز"],
  "sections": [
    {
