  "intro": "High On Life یک شوتر اول‌شخص کمدی از Squanch Games است که با طنزی بی‌پروا، اسلحه‌هایی سخنگو و دنیایی رنگارنگ و عجیب، تجربه‌ای کاملاً متفاوت از شوترهای معمولی ارائه می‌دهد. یک کارتل بیگانه می‌خواهد از انسان‌ها به‌عنوان مواد مخدر استفاده کند و فقط شما می‌توانید جلویشان را بگیرید.",
  "suits": ["علاقه‌مندان طنز بزرگسالانه", "طرفداران شوتر اول‌شخص", "بازیکنان دنبال تجربه متفاوت"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "شما یک نوجوان معمولی هستید که یک شب می‌بیند خانه‌اش به دست کارتلی بیگانه به نام G3 احاطه شده است. آن‌ها کشف کرده‌اند که انسان‌ها برای موجودات فضایی نشئه‌آورند. با پیدا کردن اسلحه‌ای سخنگو، به دنیای بیگانه‌ها فرار می‌کنید و به یک شکارچی جایزه تبدیل می‌شوید تا سران کارتل را یکی‌یکی شکار کنید.",
        "طنز بازی بسیار بی‌پرده و گاهی بی‌ادبانه است و تقریباً همه شخصیت‌ها، به‌خصوص اسلحه‌هایتان، دائم حرف می‌زنند و نظر می‌دهند."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "هر اسلحه یک شخصیت زنده با صدا و توانایی‌های خاص خودش است؛ یکی تیرهای سریع شلیک می‌کند، یکی موجودات کوچک پرتاب می‌کند و دیگری می‌تواند زمان را کند کند. این توانایی‌ها هم در مبارزه و هم در حرکت و حل معماهای محیطی کاربرد دارند.",
        "ساختار بازی ترکیبی از مأموریت‌های شکار جایزه در سیاره‌های مختلف و بازگشت به یک شهر مرکزی است که در آن می‌توانید ارتقا بخرید و رازهای جانبی کشف کنید."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "High On Life کاملاً تک‌نفره است و به اینترنت نیاز ندارد. اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید آزادانه آنلاین شوید، ظرفیت ۲ مناسب‌تر است. به‌خاطر محتوای بزرگسالانه، بازی برای کودکان مناسب نیست. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
