}$j$),

('john-carpenters-toxic-commando', $j${
  "intro": "John Carpenter's Toxic Commando یک شوتر همکاری اول‌شخص از Saber Interactive است که با حال‌وهوای فیلم‌های اکشن و وحشت دهه هشتاد و با نام جان کارپنتر، کارگردان افسانه‌ای این سبک، ساخته شده. شما و دوستانتان باید ارتش موجودات کابوس‌وار و منبع آن‌ها، «خدای لجن»، را به زیرزمین بازگردانید.",
  "suits": ["بازی همکاری با دوستان", "طرفداران اکشن و وحشت دهه هشتاد", "علاقه‌مندان شوتر"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "در آینده‌ای نزدیک، آزمایشی برای مهار انرژی هسته زمین به فاجعه‌ای وحشتناک ختم می‌شود و موجودی باستانی و شیطانی به نام خدای لجن آزاد می‌شود. زمین‌های اطراف به سرعت آلوده می‌شوند و انبوهی از موجودات جهش‌یافته از دل خاک بیرون می‌آیند. یک گروه کماندو مأموریت پیدا می‌کند که جلوی این فاجعه را بگیرد."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "تا چهار بازیکن کنترل کماندوها را برعهده می‌گیرند و هر کدام کلاسی متناسب با سبک بازی خودشان انتخاب می‌کنند. مبارزه با انبوه دشمنان بخش اصلی بازی است و سلاح‌های گرم، نارنجک‌ها، توانایی‌های ویژه و سلاح‌های سرد برای مقابله با موج‌های دشمن در اختیارتان است.",
        "خودروها هم نقش مهمی دارند؛ می‌توانید سوار ماشین‌های مختلف شوید، در زمین‌های گل‌آلود و آلوده رانندگی کنید و از آن‌ها برای عبور از میان دشمنان استفاده کنید."
      ],
      "media": "screenshot:4"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
