      ]
    }
  ]
}$j$),

('metal-gear-solid-delta-snake-eater---deluxe-edition', $j${
  "intro": "Metal Gear Solid Delta Snake Eater بازسازی کامل Metal Gear Solid 3 است؛ یکی از محبوب‌ترین قسمت‌های سری که سال ۲۰۰۴ منتشر شد. Konami در این نسخه همان داستان و دنیای جذاب را با گرافیک پیشرفته و صدای سه‌بعدی بازسازی کرده تا جنگل‌های شوروی زنده‌تر از همیشه به نظر برسند. نسخه Deluxe هم محتوای اضافه‌ای دارد که جزئیاتش را در توضیحات فروشنده ببینید.",
  "suits": ["طرفداران مخفی‌کاری", "طرفداران متال گیر", "بازیکنان داستان‌محور"],
  "sections": [
    {
