        "سال ۱۹۶۴ و در اوج جنگ سرد، نیکد اسنیک، مأمور واحد FOX، برای نجات دانشمندی شوروی به جنگل‌های آن کشور فرستاده می‌شود. اما مأموریت به‌سرعت پیچیده می‌شود؛ مربی و مادر معنوی‌اش، باس، به دشمن پیوسته و تهدیدی هسته‌ای تعادل جهان را به خطر انداخته است.",
        "این داستان آغاز ماجرای مردی است که بعدها به بیگ باس، یکی از مهم‌ترین شخصیت‌های سری، تبدیل می‌شود. روایت آن پر از لحظه‌های احساسی، شخصیت‌های عجیب و پایانی فراموش‌نشدنی است."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "بقا در جنگل بخش مهمی از بازی است. اسنیک باید غذا پیدا کند، زخم‌هایش را درمان کند و با تغییر لباس استتار و رنگ صورت، خودش را با محیط هماهنگ کند. مبارزه نزدیک با فنون CQC اجازه می‌دهد دشمنان را بی‌صدا از کار بیندازید یا بازجویی کنید.",
        "باس‌های بازی، به‌خصوص اعضای گروه کبرا، هر کدام نبردی منحصربه‌فرد دارند که می‌توان آن را به روش‌های مختلف پیش برد. این نسخه گزینه کنترل و دوربین مدرن سوم‌شخص را دارد و در عین حال امکان تجربه حس‌وحال کلاسیک را هم حفظ کرده است."
      ],
      "media": "screenshot:5"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "داستان اصلی Metal Gear Solid Delta تک‌نفره است و به اینترنت نیاز ندارد. اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید آزادانه آنلاین شوید، ظرفیت ۲ انعطاف بیشتری دارد. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
