      "paragraphs": [
        "یک گروه شش‌نفره از نژادها و کلاس‌های مختلف می‌سازید و با دید اول‌شخص در سیاه‌چال جلو می‌روید. مبارزه نوبتی است و جادو، تجهیزات و موقعیت اعضای گروه در صف جلو و عقب اهمیت زیادی دارد. بازی سخت و بی‌رحم است و مرگ اعضای گروه می‌تواند عواقب جدی داشته باشد.",
