('the-elder-scrolls-iv-oblivion---game-of-the-year-edition', $j${
  "intro": "The Elder Scrolls IV Oblivion یکی از تأثیرگذارترین نقش‌آفرینی‌های جهان‌باز تاریخ است که Bethesda Game Studios ساخته. نسخه Game of the Year علاوه بر بازی اصلی، بسته‌های الحاقی بزرگ Shivering Isles و Knights of the Nine را هم دارد. این بازی شما را آزادانه به سرزمین سیرودیل، قلب امپراتوری تمریل، می‌برد.",
  "suits": ["طرفداران نقش‌آفرینی جهان‌باز", "علاقه‌مندان فانتزی", "بازیکنان عاشق آزادی عمل"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "بازی در یک زندان آغاز می‌شود؛ جایی که امپراتور اوریل سپتیم هفتم، در حال فرار از دست قاتلانش، از سلول شما عبور می‌کند. امپراتور پیش از مرگ، مأموریتی حیاتی به شما می‌سپارد: پیدا کردن وارث مخفی‌اش. همزمان، دروازه‌هایی به دنیای شیطانی آبلیوین در سراسر سیرودیل باز می‌شوند و ارتش‌های دیو حمله می‌کنند.",
        "در کنار داستان اصلی، انجمن‌ها و گروه‌هایی مثل انجمن جنگجویان، دانشگاه جادو، انجمن دزدان و برادری تاریک، هر کدام داستان‌های طولانی و جذاب خودشان را دارند."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "Oblivion کلاس ثابت ندارد؛ مهارت‌ها با استفاده بهتر می‌شوند و می‌توانید هر ترکیبی از جنگجو، جادوگر و دزد بسازید. دنیای بازی پر از شهرها، غارها، قلعه‌ها و مأموریت‌هایی است که اغلب به‌شکلی غیرمنتظره کشف می‌شوند.",
        "Shivering Isles شما را به قلمرو شیدار، شاهزاده دیوانگی، می‌برد؛ سرزمینی عجیب و رنگارنگ با یکی از بهترین داستان‌های بسته الحاقی در تاریخ این سبک."
