      "media": "screenshot:4"
    },
    {
      "heading": "برای چه کسانی مناسب است؟",
      "paragraphs": [
        "اگر Skyrim را دوست داشتید و می‌خواهید قسمت قبلی آن را تجربه کنید، Oblivion با داستان‌های جانبی قوی‌ترش شما را غافلگیر می‌کند. توجه کنید که این بازی بعدها با نسخه Remastered برای کنسول‌های امروزی بازسازی شد؛ پیش از خرید از توضیحات فروشنده مطمئن شوید کدام نسخه عرضه می‌شود."
      ],
      "media": "screenshot:6"
    },
    {
      "heading": "کدام نوع خرید مناسب‌تر است؟",
      "paragraphs": [
        "Oblivion کاملاً تک‌نفره است و به اینترنت نیاز ندارد. اکانت ظرفیت ۱ ارزان‌ترین گزینه است، به شرط این‌که کنسول بعد از نصب آفلاین بماند. اگر می‌خواهید آزادانه آنلاین شوید، ظرفیت ۲ مناسب‌تر است. قیمت‌ها را در جدول همین صفحه مقایسه کنید."
      ]
    }
  ]
}$j$),

('final-fantasy-tactics-the-ivalice-chronicles', $j${
  "intro": "Final Fantasy Tactics The Ivalice Chronicles نسخه بهبودیافته یکی از بهترین نقش‌آفرینی‌های تاکتیکی تاریخ است. Square Enix داستان جاه‌طلبی، خیانت و شرافت در پادشاهی ایوالیس را با فیلم‌نامه‌ای به‌روزشده و غنی‌تر، صداپیشگی کامل دیالوگ‌ها و گرافیک بهتر دوباره عرضه کرده و امکانات رفاهی تازه‌ای هم به آن افزوده است.",
  "suits": ["طرفداران تاکتیک نوبتی", "طرفداران فاینال فانتزی", "بازیکنان داستان‌محور"],
  "sections": [
    {
