('uncharted-4-a-thief-s-end', $j${
  "intro": "Uncharted 4 A Thief's End پایان ماجراهای نیتن دریک، گنج‌یاب ماجراجوی Naughty Dog، است. چند سال پس از آخرین ماجرایش، دریک که بازنشسته شده، ناچار دوباره به دنیای دزدان کشیده می‌شود؛ این بار با انگیزه‌ای بسیار شخصی‌تر. روی PS5، این بازی معمولاً در مجموعه Legacy of Thieves Collection همراه با Uncharted: The Lost Legacy و با کیفیت بهتر عرضه می‌شود.",
