('far-cry-6-game-of-the-year-edition', $j${
  "intro": "Far Cry 6 Game Of The Year Edition نسخه کامل قسمت ششم سری Far Cry است که بازی اصلی را همراه با همه محتوای Season Pass، بسته Ultimate، به‌روزرسانی‌ها و بسته الحاقی Lost Between Worlds عرضه می‌کند. به یارا خوش آمدید؛ بهشتی استوایی که در زمان متوقف شده و زیر حکومت دیکتاتوری بی‌رحم قرار دارد.",
