        "محتوای Season Pass شما را در نقش شرورهای معروف قسمت‌های قبلی سری قرار می‌دهد و Lost Between Worlds ماجرایی علمی‌تخیلی در دنیایی موازی اضافه می‌کند."
      ]
    },
    {
