  "suits": ["علاقه‌مندان شوتر و استراتژی", "طرفداران روگ‌لایک", "دوستداران سبک بصری کمیک"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
      "paragraphs": [
        "گروهی از یاغیان فضایی، که بیشترشان شکار شده‌اند، باید دوباره دور هم جمع شوند و از دست کسانی که در تعقیبشان هستند، به سیاره‌ای امن برسند. هر یاغی شخصیت، سلاح و توانایی ویژه خودش را دارد و طنز تلخ و دیالوگ‌های بامزه، حال‌وهوای وسترن فضایی بازی را می‌سازند. سبک بصری کمیک‌گونه هم امضای این استودیوست."
      ],
      "media": "screenshot:2"
    },
    {
      "heading": "گیم‌پلی چطور است؟",
      "paragraphs": [
        "روی نقشه کهکشان، مسیرتان را از سیاره‌ای به سیاره دیگر انتخاب می‌کنید و تصمیم می‌گیرید کدام یاغی‌ها را به هر مأموریت بفرستید. در سیاره‌ها، نبرد به یک شوتر اول‌شخص سریع تبدیل می‌شود که در آن می‌توانید میان اعضای گروه جابه‌جا شوید. روابط میان یاغی‌ها هم اهمیت دارد؛ بعضی با هم کنار می‌آیند و بعضی نه."
