      ]
    }
  ]
}$j$),

('funko-fusion', $j${
  "intro": "Funko Fusion یک بازی اکشن سوم‌شخص از 10:10 Games است که سراسر جشن طرفداران دنیای فیلم، سریال، بازی و کمیک است. شخصیت‌هایی از مجموعه‌های مختلف به شکل عروسک‌های بامزه فانکو پاپ درآمده‌اند و شما در دنیاهایی دست‌ساز، الهام‌گرفته از همین مجموعه‌ها، ماجراجویی می‌کنید.",
