  "sections": [
    {
      "heading": "ایده اصلی",
      "paragraphs": [
        "هر دنیا از یک مجموعه سینمایی یا تلویزیونی معروف الهام گرفته و شما در قالب شخصیت‌های فانکو، لحظه‌هایی آشنا از آن‌ها را با لحنی طنزآمیز تجربه می‌کنید. شوخی‌ها، ارجاع‌ها و اشاره‌ها به فیلم‌ها و سریال‌های محبوب، بخش بزرگی از جذابیت بازی برای طرفداران است."
