      ]
    }
  ]
}$j$),

('humankind', $j${
  "intro": "Humankind یک بازی استراتژی نوبتی تاریخی از Amplitude Studios است که سگا منتشر کرده. در این بازی کل روایت تاریخ بشر را از نو می‌نویسید؛ با ترکیب تا ۶۰ فرهنگ تاریخی، مردمتان را از عصر باستان تا دوران مدرن هدایت می‌کنید و تمدنی می‌سازید که به اندازه خودتان منحصربه‌فرد است.",
