      "paragraphs": [
        "نبردها نوبتی‌اند، اما با فشردن دکمه در لحظه درست، ضربه‌ها قوی‌تر می‌شوند و آسیب دریافتی کمتر. دشمنان پیش از حملات بزرگ قفل‌هایی نشان می‌دهند که باید با ضربه‌های نوع مشخص بشکنید. خبری از نبردهای تصادفی هم نیست و کاوش روان است؛ شخصیت‌ها می‌توانند بپرند، شنا کنند و بالا بروند.",
