('panda-hero', $j${
  "intro": "Panda Hero یک پلتفرمر آرکید و ماجرایی سبک از Joindots است که TREVA Entertainment منتشر کرده. شعار بازی ساده است: پاندای درونتان را آزاد کنید! در نقش پاندایی قهرمان، از مراحل پرمانع عبور می‌کنید، با دشمنان می‌جنگید و راهتان را تا پایان ماجرا باز می‌کنید.",
