('vampire-the-masquerade-swansong', $j${
  "intro": "Vampire The Masquerade Swansong یک نقش‌آفرینی روایی از Big Bad Wolf است که Nacon بر اساس دنیای کالت نقش‌آفرینی رومیزی «خون‌آشام: بالماسکه» منتشر کرده. در این بازی هر انتخاب شما سرنوشت سه شخصیت اصلی را تعیین می‌کند و سیاست، توطئه و بقا در جامعه پنهان خون‌آشام‌های بوستون در مرکز ماجراست.",
