      "paragraphs": [
        "بازی مبارزه سنتی ندارد و تمرکزش بر گفت‌وگو، تحقیق و تصمیم‌گیری است. هر شخصیت مهارت‌ها و قدرت‌های خون‌آشامی خاص خودش را دارد؛ از نفوذ ذهنی و فریب تا نامرئی شدن و جابه‌جایی سریع. گفت‌وگوهای مهم مثل نبردهای کلامی طراحی شده‌اند و باید با شناخت حریف، استدلال درست را انتخاب کنید.",
