('gran-turismo-7-25-th-anniversary-edition', $j${
  "intro": "Gran Turismo 7 25th Anniversary Edition نسخه ویژه بیست‌وپنجمین سالگرد سری گرن توریسمو است که Polyphony Digital ساخته. GT7 بهترین ویژگی‌های «شبیه‌ساز رانندگی واقعی» را کنار هم جمع کرده؛ چه رقابت‌طلب باشید و چه رانندگی آرام را دوست داشته باشید، چه کلکسیونر خودرو، تیونر، طراح ظاهر یا عکاس. محتوای اضافه این نسخه را در توضیحات فروشنده ببینید.",
  "suits": ["طرفداران شبیه‌ساز رانندگی", "علاقه‌مندان خودرو", "بازیکنان رقابتی"],
  "sections": [
