        "رانندگی با پشتیبانی کامل از بازخورد لمسی و ماشه‌های دسته DualSense، حس هر خودرو و سطح جاده را منتقل می‌کند. صدها خودرو، ده‌ها پیست واقعی و خیالی، حالت عکاسی پیشرفته و ابزار طراحی ظاهر، عمق زیادی به تجربه داده‌اند."
