('front-mission', $j${
  "intro": "Front Mission روی PS5 معمولاً به Front Mission 1st: Remake اشاره دارد؛ بازسازی امروزی اولین قسمت سری استراتژی نوبتی Front Mission که در آن جوخه‌ای از ربات‌های جنگی غول‌پیکر به نام وانزر را هدایت می‌کنید. پیش از خرید از توضیحات فروشنده مطمئن شوید دقیقاً همین نسخه را می‌خرید.",
  "suits": ["علاقه‌مندان تاکتیک نوبتی", "طرفداران ربات‌های جنگی", "بازیکنان داستان‌محور"],
  "sections": [
    {
      "heading": "داستان و حال‌وهوا",
