        "سال ۲۰۷۰ است و جنگی میان دو قدرت بزرگ بر سر جزیره‌ای کوچک در اقیانوس آرام، که منابع ارزشمندی دارد، شعله‌ور شده. داستان از نگاه خلبانی روایت می‌شود که پس از یک حادثه تلخ در آغاز جنگ، به گروهی مزدور می‌پیوندد و حقیقت پشت پرده درگیری را کشف می‌کند. بازی دو کمپین از نگاه دو طرف درگیری دارد و روایتش جدی و سیاسی است."
      ]
    },
    {
