('star-wars-outlaws-special-edition', $j${
  "intro": "Star Wars Outlaws Special Edition نسخه ویژه اولین بازی جهان‌باز جنگ ستارگان است که Massive Entertainment ساخته و یوبی‌سافت منتشر کرده. داستان میان وقایع «امپراتوری ضربه می‌زند» و «بازگشت جدای» می‌گذرد و شما را در نقش یک خلافکار در دنیای زیرزمینی کهکشان قرار می‌دهد. محتوای اضافه این نسخه را در توضیحات فروشنده ببینید.",
